# Heat and Cooking Methods (cuheat): lessons.
LESSONS = {
"heat-transfer": LES([
 P("Every cooking method is a way of getting heat into food. There are only three ways heat moves, and most methods use all three."),
 K("<b>Conduction:</b> heat passes by direct contact, from burner to pan to food, and from the outside of the food to its center. <b>Convection:</b> a moving fluid (air, water, oil, steam) carries heat; a convection oven's fan speeds it up. <b>Radiation:</b> heat travels as infrared light from a glowing source, as in a broiler, a grill or a salamander."),
 TB(["Method", "Main way heat arrives"], [["Sautéing", "Conduction from the pan"], ["Deep-frying", "Convection in hot oil"], ["Roasting", "Convection of hot air, plus radiation from the oven walls"], ["Broiling", "Radiation from above"], ["Boiling and poaching", "Convection in water"], ["Steaming", "Steam condensing on the food (it gives up a lot of heat as it turns back to water)"]]),
 W("Inside food, heat moves only by conduction, which is slow. That's why thick food cooks slowly and why a very hot oven can burn the outside of a roast before the center is done. Thin pieces, or lower heat for big pieces, give the inside time to catch up."),
 EX("Which way?", "A salamander browns the top of a crème brûlée.", ["The heat comes from a glowing element above, through the air, as infrared light."], "Radiation."),
 M("Turning a convection oven to the same temperature a recipe gives for a still oven. Many recipes and oven makers suggest about 25°F lower, or a shorter time, because moving air cooks faster."),
 DRILL("Put two identical potatoes in a 400°F oven: one whole, one cut in half. Check both with a skewer every 10 minutes. Which is done first, and why?"),
 SCI([("/physics/physical-science/heat-transfer/", "Conduction, convection and radiation", "the physics of heat transfer"), ("/physics/physics-2/conduction-rate/", "Rate of heat conduction", "why thickness matters so much")]),
 TRY,
], "cia"),

"browning": LES([
 P("The brown crust on bread, seared steak, roasted coffee and toast is where much of the flavor lives. Two different chemical changes make it."),
 K("<b>The Maillard reaction</b> happens when amino acids (from proteins) and certain sugars react under heat, making hundreds of flavor and aroma compounds and brown color. It goes quickly above about 280°F to 300°F. <b>Caramelization</b> is sugar alone breaking down under heat, starting at about 320°F for table sugar, giving caramel flavors and color."),
 W("Water boils at 212°F at sea level, so a wet surface can't get hot enough to brown until it dries. That is why cooks pat meat dry, don't crowd the pan, and preheat it well. It is also why boiled meat is gray and roasted meat is brown."),
 TB(["To brown more", "To brown less"], [["Dry the surface", "Keep it moist or covered"], ["Higher heat, hot pan", "Lower heat"], ["Leave space between pieces", "Crowd the pan (steam)"], ["A little sugar or milk in a glaze", "Acid slows Maillard browning"], ["Leave it alone until it releases", "Stir constantly"]]),
 EX("Why so gray?", "Mushrooms piled in a small pan release water and stay gray for ten minutes.", ["The water keeps the surface near 212°F, below browning temperatures.", "Spread them out, use high heat, and salt them after they brown."], "They are steaming, not browning."),
 M("Moving food too soon. A sear sticks at first and then releases as the crust forms. Pull it early and you tear the crust."),
 DRILL("Sear two pieces of chicken: one patted dry, one straight from the package. Compare color and flavor.", "Cook ½ cup sugar in a heavy pan without stirring, swirling as it melts, until amber. Watch how fast it darkens at the end."),
 SCI([("/chemistry/chemistry/collision-theory/", "Collision theory and reaction rate", "why browning speeds up as it gets hotter"), ("/biology/high-school-biology/proteins/", "Proteins", "the amino acids that react")]),
 TRY,
], "g_maillard"),

"saute-panfry": LES([
 P("Sauté means \"jump\" in French: small pieces of food toss in a hot pan with a little fat. It is the fastest way to cook, and the most demanding."),
 K("<b>Sauté:</b> a hot pan, a thin film of fat, small or thin pieces, cooked fast and moved often. <b>Stir-fry:</b> the same idea in a wok at very high heat, food constantly moving. <b>Pan-fry:</b> more fat (about ⅛ to ¼ inch up the sides), larger pieces, often breaded, cooked on one side until browned, then turned once."),
 LI("Heat the pan first, then the fat; add food when the fat shimmers.",
    "Pat food dry; season just before it goes in.",
    "Don't crowd. Cook in batches if you need to.",
    "Choose a fat whose smoke point suits the heat: clarified butter or a neutral oil for high heat; whole butter burns sooner.",
    "Standard breading: flour, then beaten egg, then crumbs."),
 W("A cold pan with cold oil lets food sit and absorb fat while it slowly heats. A hot pan sears the surface at once, so food releases and absorbs less oil."),
 EX("Sauté or pan-fry?", "Breaded pork cutlets cooked in ¼ inch of oil, turned once.", ["More fat, breaded, turned once."], "Pan-frying."),
 SAFE("Lay food into hot fat away from you so splashes go the other way.", "Keep pan handles turned in from the edge of the stove.", "Use a dry towel or mitt for hot handles; a wet towel lets heat straight through."),
 M("Adding salt to mushrooms or onions at the start when you want them browned; salt draws water out and they steam. Salt them once they color, or at the start if you want them soft."),
 DRILL("Sauté a sliced onion three ways: medium-low for 30 minutes (caramelized), medium for 10 (golden), and high for 4 (charred edges, crisp). Taste the difference.", "Bread and pan-fry two chicken cutlets with the flour, egg, crumb method."),
 MP([("guides/fats/#smoke-point", "What smoke point means", "choosing a fat for the heat"), ("recipes/chicken-chasseur/", "Hunter's Chicken (Chicken Chasseur)", "a classic sauté finished with a pan sauce")]),
 TRY,
], "g_braise", "cia"),

"deep-fry": LES([
 P("Deep-frying cooks food fully surrounded by hot oil. Done right, the outside is crisp and the inside steams in its own moisture."),
 K("<b>Frying temperatures</b> are usually about <b>325°F to 375°F</b>, set by what you fry: lower for thick food that needs to cook through, higher for small or already-cooked food. <b>Fry in small batches</b> so the oil temperature doesn't crash, drain on a rack, and season while hot."),
 LI("Pat food dry; let excess batter drip off.",
    "Lower food in gently, away from you, with a basket or spider.",
    "Keep the oil at the right temperature with a thermometer; it drops when food goes in.",
    "Strain oil after use; replace it when it darkens, smells, foams or smokes at frying temperature."),
 SAFE("Never pour water on a grease fire: it can make burning oil spray and spread the fire. For a small pan fire, slide a lid over the pan, turn off the heat, and leave the pan where it is until it cools.",
      "If a fire is not small and contained, get everyone out and call 911.",
      "Commercial kitchens use Class K fire extinguishers for cooking oil fires, along with built-in hood suppression systems; only trained people should use extinguishers.",
      "Never put wet or icy food into hot oil, never fill a pot more than about half full of oil, and never leave hot oil alone.",
      "Let oil cool completely before moving or straining it; OSHA lists fryers as a leading cause of burns in restaurants."),
 W("Too cool, and food soaks up oil and turns greasy. Too hot, and the outside browns before the inside cooks. Watching the thermometer and frying in batches fixes both."),
 EX("Batch size", "Your fryer holds 3 quarts of oil at 350°F. Adding 2 pounds of cold potatoes drops it to 300°F. What should you do next time?", ["A big drop means the batch was too large for the oil.", "Fry smaller batches and let the oil recover between them."], "Fry smaller batches."),
 M("Frying straight from the freezer with ice crystals on the food. The water turns to steam instantly and the oil can spatter or foam over."),
 DRILL("Heat 2 inches of oil in a heavy pot, no more than half full, with a clip-on thermometer. Fry a few slices of potato at 325°F and at 375°F; compare. Keep a lid beside the pot the whole time."),
 MP([("guides/fats/", "Cooking Fats Compared", "how hot each fat can go")]),
 TRY,
], "osha", "cfd", "g_braise"),

"dry-oven": LES([
 P("Roasting, grilling and broiling are dry-heat methods: no liquid, just hot air, flame or glowing elements. They brown well and suit tender foods."),
 K("<b>Roasting:</b> food in an open pan surrounded by hot air in an oven (baking is the same method for bread and pastry). <b>Grilling:</b> food on grates over a heat source. <b>Broiling:</b> food under a strong heat source. For large pieces, cooks often <b>sear</b> first at high heat for color, then finish at a lower temperature so the center cooks evenly."),
 V("cu-carry", {"mode": "roast"}, "Oven temperature changes how even the meat is: try 450°F and 300°F with the same final reading."),
 LI("Most roasts can go into the oven straight from the refrigerator; they just take a little longer.",
    "Use a rack so hot air reaches the bottom.",
    "Use a probe thermometer; pull a little early for carryover (next course: Proteins).",
    "Grill: clean, oiled grates; a hot zone and a cooler zone; move food rather than burning it.",
    "Broil: watch closely; the distance from the element sets how fast it browns."),
 W("At a high oven temperature, the outer layer of a roast gets far hotter than the center, leaving a thick gray band. At a lower temperature the heat spreads more evenly, so more of the slice is the doneness you wanted. That is the idea behind slow-roasting and the reverse sear (low oven first, sear at the end)."),
 EX("Pick the method", "You want to brown the top of a gratin that is already cooked through.", ["Heat from above, fast."], "Broil (or use a salamander)."),
 M("Cutting into meat to check doneness. Juices run out, and you can't see temperature anyway. Use a thermometer."),
 SAFE("Use the safe minimum temperatures from the Food Safety course, checked in the thickest part.", "Keep a grill away from walls and anything that can burn, and never leave it alone while lit."),
 DRILL("Roast two small chickens or two pork tenderloins, one at 450°F and one at 325°F, to the same internal temperature. Slice and compare the gray band."),
 MP([("recipes/delmonico-steak/", "Delmonico Steak with Parsley Butter", "a classic grilled steak")]),
 TRY,
], "usda_temps", "cia"),

"moist-heat": LES([
 P("Moist-heat methods cook food in water, stock or steam. The temperature of the liquid matters more than any other thing."),
 K("<b>Poach:</b> about 160°F to 180°F; the liquid barely moves (eggs, fish, fruit). <b>Simmer:</b> about 185°F to 205°F; small bubbles break gently (stocks, stews, beans). <b>Boil:</b> 212°F at sea level; large, rolling bubbles (pasta, blanching green vegetables). <b>Steam:</b> food above boiling water in a closed space; it keeps shape, color and nutrients well."),
 TB(["Height above sea level", "Water boils at about"], [["Sea level", "212°F"], ["2,500 ft", "207°F"], ["5,000 ft", "203°F"], ["7,500 ft", "198°F"], ["10,000 ft", "194°F"]], "Water boils about 1°F lower for every 500 feet of height"),
 W("Air pressure is lower in the mountains, so water boils at a lower temperature, and food in boiling water cooks more slowly. Pasta and beans take longer in Denver than in Miami, and candy recipes need adjusting."),
 EX("Mountain boil", "About what temperature does water boil at 6,000 feet?", ["About 1°F less per 500 ft: $6000 \\div 500 = 12$.", "$212 - 12 = 200$."], "About 200°F."),
 M("Boiling food that should be poached. A rolling boil toughens fish and chicken and breaks up eggs. Turn the heat down until the liquid barely moves."),
 DRILL("Heat a pot of water with a thermometer in it. Note what the surface looks like at 170°F, 190°F and 212°F, so you can judge without the thermometer later.", "Poach an egg in water at about 180°F, and another at a hard boil. Compare."),
 SCI([("/chemistry/general-chemistry-1/freezing-boiling-points/", "Freezing point depression and boiling point elevation", "what salt does (and doesn't do) to boiling water"), ("/chemistry/chemistry/heating-curves/", "Heating curves and phase changes", "why water stays at 212°F while it boils")]),
 TRY,
], "cia", "g_braise"),

"braise-stew": LES([
 P("Tough cuts like chuck, shank and short ribs become tender with time and gentle moist heat. Braising and stewing are how."),
 K("<b>Braise:</b> brown large pieces, add liquid partway up (about a third to halfway), cover, and cook slowly in a low oven or at a bare simmer until tender. <b>Stew:</b> the same idea with smaller pieces covered in liquid. Slowly, the tough connective tissue (<b>collagen</b>) breaks down into <b>gelatin</b>, which gives body to the sauce and makes the meat moist."),
 LI("Brown the meat well, in batches, for flavor; remove it.",
    "Cook aromatics (onion, carrot, celery) in the same pan.",
    "Deglaze with wine or stock, scraping up the browned bits.",
    "Return the meat, add liquid, cover, and cook at a gentle simmer, often in an oven at about 300°F to 325°F.",
    "Cook until a fork slides in easily, then reduce the liquid into a sauce."),
 W("Collagen needs time at temperatures around a simmer to turn into gelatin. A hard boil drives moisture out of the muscle fibers faster than the collagen softens, so meat can end both stringy and dry even though it sat in liquid."),
 EX("Braise or stew?", "Lamb shanks, browned whole, cooked covered with wine halfway up.", ["Large pieces, partly covered in liquid."], "A braise."),
 M("Skipping the browning. The sauce lacks the deep flavor that the Maillard reaction builds."),
 DRILL("Braise 2 pounds of chuck in a covered pot at 300°F. Test with a fork every 30 minutes after the first 1½ hours and note when it turns tender.", "Chill the braise overnight and lift off the fat that sets on top. Notice how the liquid has jelled from the gelatin."),
 MP([("recipes/chicken-chasseur/", "Hunter's Chicken", "a quick braise-style sauté with a sauce")]),
 TRY,
], "g_braise", "cia"),

"sous-vide": LES([
 P("Sous vide (\"under vacuum\") means sealing food in a bag and cooking it in a water bath held at an exact temperature, often for a long time. A steak cooked at 131°F comes out the same pink from edge to edge."),
 K("<b>Safety comes from time at temperature.</b> Either cook to the safe minimum internal temperature for that food, or follow a <b>published time-and-temperature table</b>. For example, the FDA Food Code's table for whole roasts of beef allows 130°F held for 112 minutes, 135°F for 36 minutes, 140°F for 12 minutes or 145°F for 4 minutes, counted after the center reaches that temperature."),
 TB(["Roast temperature", "Hold at least"], [["130°F", "112 minutes"], ["133°F", "56 minutes"], ["135°F", "36 minutes"], ["138°F", "18 minutes"], ["140°F", "12 minutes"], ["142°F", "8 minutes"], ["145°F", "4 minutes"]], "From the Food Code's whole-roast table (as published by the Minnesota Department of Health); the time starts once the center reaches the temperature"),
 LI("Sear the outside after cooking for color; the bath can't brown food.",
    "If food is not served right away, chill it quickly by the two-stage cooling rule (ice water works well) and keep it cold.",
    "Use bags made for cooking.",
    "In restaurants, vacuum-sealing and sous vide are \"reduced-oxygen packaging\", and the Food Code requires a HACCP plan for them."),
 W("Germs die faster the hotter they get. At 145°F a few minutes is enough; at 130°F it takes nearly two hours. Low temperatures are safe only when the time is long enough, and the time is measured at the center of the food."),
 EX("How long?", "A beef roast's center has reached 135°F in a water bath. By the Food Code's table, how long must it hold there?", ["Read the table: 135°F needs 36 minutes."], "36 minutes."),
 M("Starting the clock when food goes in the bath. The table's time starts when the center reaches the bath temperature, which can take an hour or more for thick pieces."),
 DRILL("If you have a circulator, cook one steak in a 145°F bath until its center reaches 145°F and cook another in a pan to the same reading. Slice both and compare how far the gray band goes."),
 TRY,
], "mn_roast", "foodcode", "g_sousvide"),
}
